'use client';
// Fleet operations: what needs attention, vehicle documents, maintenance plans, work orders, the parts store,
// drivers (licences, handovers, violations), places on the map with rep visits, and monthly costs.
import React,{useEffect,useMemo,useState} from 'react';
import L from 'leaflet';
import {Bell,FileText,Wrench,ClipboardList,Package,IdCard,MapPinned,Coins,Plus,Pencil,Trash2,Eye,ArrowDownToLine,ArrowUpFromLine,CheckCheck,ArrowLeftRight,FileSpreadsheet,TriangleAlert} from 'lucide-react';
import {toast} from 'sonner';
import {db,unwrap,Row,message,num,uploadImage,signed} from '@/lib/gd';
import {useUI} from './platform';
import {Empty} from './public-site';
import {PageHead,Modal,FilePick} from './ui';
import {MapView,drawPlaces} from './map';
const usePlaces=()=>useTable('places','id,name,kind,lat,lng,radius_m,is_active,address,phone',['name',true]);

type T=(ar:string,en:string)=>string;
const today=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
const daysUntil=(d?:string|null)=>d?Math.round((Date.parse(d)-Date.parse(today()))/86400000):null;
const money=(v:any,t:T)=>v==null||v===''?'—':num(Math.round(Number(v)))+' '+t('ج.م','EGP');
const fmtDate=(v:any,lang:string)=>v?new Date(v).toLocaleDateString(lang==='ar'?'ar-EG':'en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
export const DOC_KINDS:Record<string,[string,string]>={license:['رخصة العربية','Vehicle licence'],insurance:['التأمين','Insurance'],inspection:['الفحص الفني','Inspection'],permit:['تصريح','Permit'],other:['مستند آخر','Other document']};
const SERVICE:Record<string,[string,string]>={oil_change:['تغيير زيت','Oil change'],maintenance:['صيانة','Maintenance'],spare_part:['قطعة غيار','Spare part'],tires:['كاوتش','Tyres'],battery:['بطارية','Battery'],other:['أي مصروف صيانة','Any service expense']};
const WO_STATUS:Record<string,[string,string,string]>={open:['مفتوح','Open','pill-amber'],in_progress:['في الورشة','In the workshop','pill-blue'],done:['اتقفل','Done','pill-green'],cancelled:['ملغي','Cancelled','pill-gray']};
const PRIORITY:Record<string,[string,string]>={low:['عادي','Low'],normal:['متوسط','Normal'],high:['عاجل','Urgent']};
const VIOLATIONS:Record<string,[string,string]>={speeding:['سرعة زيادة','Speeding'],traffic_fine:['مخالفة مرور','Traffic fine'],accident:['حادثة','Accident'],damage:['تلفيات في العربية','Vehicle damage'],late:['تأخير','Lateness'],other:['أخرى','Other']};
const PLACE_KINDS:Record<string,[string,string,string]>={factory:['المصنع','Factory','#e30613'],warehouse:['مخزن','Warehouse','#1f2937'],customer:['عميل','Customer','#2563eb'],supplier:['مورد','Supplier','#16a34a'],other:['مكان آخر','Other','#9333ea']};

function useTable(name:string,select='*',order?:[string,boolean]){const {version}=useUI();const [rows,setRows]=useState<Row[]|null>(null);
 const load=async()=>{let q:any=db().from(name).select(select);if(order)q=q.order(order[0],{ascending:order[1]});const r=await q.limit(5000);if(r.error){toast.error(message(r.error));setRows([])}else setRows(r.data||[])};
 useEffect(()=>{load()},[version]);return {rows,load}}
function useVehicles(){return useTable('vehicles','id,plate_number,type_id,status,model,initial_odometer',['plate_number',true]).rows||[]}
function useDrivers(){const [reps,setReps]=useState<Row[]>([]);useEffect(()=>{db().rpc('tracking_reps').then(r=>setReps(r.data||[]))},[]);return reps}

function ExpiryBadge({date}:{date?:string|null}){const {t}=useUI();const d=daysUntil(date);if(d==null)return <span className="muted">—</span>;
 if(d<0)return <span className="pill pill-red">{t(`منتهي من ${-d} يوم`,`Expired ${-d} d ago`)}</span>;if(d<=30)return <span className="pill pill-amber">{t(`باقي ${d} يوم`,`${d} days left`)}</span>;return <span className="pill pill-green">{t(`باقي ${d} يوم`,`${d} days left`)}</span>}

// One small form engine for every add/edit dialog on this page.
type Field={key:string,label:string,type?:'text'|'number'|'date'|'select'|'textarea'|'photo',options?:[string,string][],required?:boolean,step?:string,full?:boolean,hint?:string};
function FormModal({title,fields,initial,onClose,onSave}:{title:string,fields:Field[],initial:Row,onClose:()=>void,onSave:(v:Row,photo:File|null)=>Promise<void>}){const {t}=useUI();const [v,setV]=useState<Row>(initial),[photo,setPhoto]=useState<File|null>(null),[busy,setBusy]=useState(false);
 return <Modal title={title} onClose={onClose}><form className="form-grid" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await onSave(v,photo);onClose()}catch(err){toast.error(message(err))}finally{setBusy(false)}}}>
  {fields.map(f=>{const Wrap:any=f.type==='photo'?'div':'label';return <Wrap key={f.key} className={'field'+(f.full||f.type==='textarea'||f.type==='photo'?' full':'')}>{f.label}
   {f.type==='select'?<select required={f.required} value={v[f.key]??''} onChange={e=>setV(o=>({...o,[f.key]:e.target.value}))}>{!f.required&&<option value="">—</option>}{f.options!.map(([k,l])=><option key={k} value={k}>{l}</option>)}</select>
   :f.type==='textarea'?<textarea rows={2} value={v[f.key]??''} onChange={e=>setV(o=>({...o,[f.key]:e.target.value}))}/>
   :f.type==='photo'?<FilePick label={t('اختار صورة','Choose a photo')} accept="image/*" file={photo} onChange={setPhoto}/>
   :<input required={f.required} type={f.type||'text'} step={f.step} inputMode={f.type==='number'?'decimal':undefined} value={v[f.key]??''} onChange={e=>setV(o=>({...o,[f.key]:e.target.value}))}/>}
   {f.hint&&<small className="muted">{f.hint}</small>}</Wrap>})}
  <div className="modal-foot full"><button type="button" className="btn btn-ghost" onClick={onClose}>{t('إلغاء','Cancel')}</button><button className="btn btn-red" disabled={busy}>{busy?<span className="spinner small light"/>:t('حفظ','Save')}</button></div></form></Modal>}
const clean=(v:Row,numbers:string[]=[])=>{const r:Row={};for(const [k,x] of Object.entries(v)){if(k==='id'||k.startsWith('_'))continue;r[k]=x===''?null:numbers.includes(k)&&x!=null?Number(x):x}return r};
async function save(table:string,v:Row,numbers:string[]=[]){const body=clean(v,numbers);unwrap(v.id?await db().from(table).update(body).eq('id',v.id):await db().from(table).insert(body))}
async function remove(table:string,id:string,t:T,key='id'){if(!confirm(t('متأكد إنك عاوز تمسح ده؟','Delete this?')))return false;unwrap(await db().from(table).delete().eq(key,id));return true}
async function openFile(key:string){try{window.open(await signed('factory-files',key,true),'_blank','noopener')}catch(e){toast.error(message(e))}}
async function exportSheet(name:string,header:string[],rows:any[][],rtl:boolean){const Excel=(await import('exceljs')).default;const wb=new Excel.Workbook();const s=wb.addWorksheet(name.slice(0,30));s.views=[{rightToLeft:rtl}];s.addRow(header);for(const r of rows)s.addRow(r);s.getRow(1).font={bold:true};s.columns.forEach(c=>c.width=18);const out=await wb.xlsx.writeBuffer();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([out],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));a.download=name+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

const TABS:[string,string,string,any][]=[['alerts','التنبيهات','Alerts',Bell],['documents','المستندات','Documents',FileText],['maintenance','خطة الصيانة','Maintenance plan',Wrench],['orders','أوامر الشغل','Work orders',ClipboardList],['parts','قطع الغيار','Parts store',Package],['drivers','السواقين','Drivers',IdCard],['places','الأماكن والزيارات','Places & visits',MapPinned],['costs','التكاليف','Costs',Coins]];

export default function FleetOpsPage({access}:{access:Row}){const {t}=useUI();const can=(p:string)=>!!access.permissions?.includes(p);const manage=can('fleet.manage');
 const [tab,setTab]=useState(()=>{const q=new URLSearchParams(location.search).get('tab');return TABS.some(x=>x[0]===q)?q!:'alerts'});
 const pick=(k:string)=>{setTab(k);history.replaceState(null,'','/admin/fleet-ops'+(k==='alerts'?'':'?tab='+k))};
 return <><PageHead title={t('إدارة الأسطول','Fleet management')} subtitle={t('المستندات والصيانة وأوامر الشغل وقطع الغيار والسواقين والأماكن والتكاليف في مكان واحد.','Documents, maintenance, work orders, parts, drivers, places and costs in one place.')}/>
  <div className="segmented fleet-ops-tabs" role="tablist">{TABS.map(([k,a,e,Icon])=><button key={k} role="tab" aria-selected={tab===k} className={tab===k?'active':''} onClick={()=>pick(k)}><Icon size={15}/>{t(a,e)}</button>)}</div>
  {tab==='alerts'?<Alerts go={pick}/>:tab==='documents'?<Documents manage={manage}/>:tab==='maintenance'?<Maintenance manage={manage} go={pick}/>:tab==='orders'?<Orders manage={manage}/>:tab==='parts'?<Parts manage={manage}/>:tab==='drivers'?<Drivers manage={manage}/>:tab==='places'?<Places manage={manage}/>:<Costs/>}</>}

/* ───────── Alerts ───────── */
export function alertText(a:Row,t:T){switch(a.kind){
 case 'document':return [`${t(DOC_KINDS[a.doc_kind]?.[0]||'مستند',DOC_KINDS[a.doc_kind]?.[1]||'Document')} — ${a.plate_number}`,a.days<0?t(`منتهي من ${-a.days} يوم`,`expired ${-a.days} days ago`):t(`بينتهي بعد ${a.days} يوم`,`expires in ${a.days} days`)];
 case 'maintenance':return [`${a.item} — ${a.plate_number}`,a.km_left!=null&&a.km_left<=0||a.days!=null&&a.days<0?t('ميعادها فات','overdue'):a.km_left!=null?t(`باقي ${num(Math.round(a.km_left))} كم`,`${num(Math.round(a.km_left))} km left`):t(`باقي ${a.days} يوم`,`${a.days} days left`)];
 case 'license':return [t(`رخصة سواقة ${a.driver_name}`,`${a.driver_name}'s driving licence`),a.days<0?t(`منتهية من ${-a.days} يوم`,`expired ${-a.days} days ago`):t(`بتنتهي بعد ${a.days} يوم`,`expires in ${a.days} days`)];
 case 'stock':return [t(`${a.name} قرّب يخلص`,`${a.name} is running low`),t(`الموجود ${num(a.qty)} والحد الأدنى ${num(a.min_qty)}`,`${num(a.qty)} in stock, minimum ${num(a.min_qty)}`)];
 case 'work_order':return [t(`أمر شغل #${a.number} — ${a.plate_number}`,`Work order #${a.number} — ${a.plate_number}`),t(`${a.title} — متأخر ${-a.days} يوم`,`${a.title} — ${-a.days} days late`)];
 default:return [a.kind,'']}}
const ALERT_TAB:Record<string,string>={document:'documents',maintenance:'maintenance',license:'drivers',stock:'parts',work_order:'orders'};
const ALERT_ICON:Record<string,any>={document:FileText,maintenance:Wrench,license:IdCard,stock:Package,work_order:ClipboardList};
function Alerts({go}:{go:(k:string)=>void}){const {t,version}=useUI();const [alerts,setAlerts]=useState<Row[]|null>(null);
 useEffect(()=>{db().rpc('fleet_alerts').then(r=>setAlerts(r.data||[]))},[version]);
 const count=(k:string)=>(alerts||[]).filter(a=>a.kind===k).length;
 return <><div className="stat-cards five">{([['document','مستندات بتنتهي','Documents expiring'],['maintenance','صيانة مستحقة','Maintenance due'],['work_order','أوامر شغل متأخرة','Late work orders'],['stock','قطع قرّبت تخلص','Parts running low'],['license','رخص سواقة','Driving licences']] as const).map(([k,a,e])=><button key={k} className={'stat-card '+(count(k)?'tone-red':'tone-green')} onClick={()=>go(ALERT_TAB[k])}><b>{alerts?num(count(k)):'—'}</b><span>{t(a,e)}</span></button>)}</div>
  <section className="card">{alerts===null?<div className="center-block"><span className="spinner"/></div>:alerts.length?<ul className="ops-alerts">{alerts.map((a,i)=>{const [title,detail]=alertText(a,t);const Icon=ALERT_ICON[a.kind]||TriangleAlert;return <li key={i} className={'sev-'+a.severity} onClick={()=>go(ALERT_TAB[a.kind])}><Icon size={18}/><span><b>{title}</b><small>{detail}</small></span><span className={'pill '+(a.severity==='high'?'pill-red':'pill-amber')}>{a.severity==='high'?t('عاجل','Urgent'):t('قريب','Soon')}</span></li>})}</ul>
   :<Empty title={t('مفيش أي حاجة محتاجة متابعة دلوقتي','Nothing needs attention right now')} detail={t('ضيف مستندات العربيات ورخص السواقين، وسجّل الصيانة، والتنبيهات هتظهر هنا قبل مواعيدها.','Add vehicle documents and driving licences and log services; alerts appear here before they are due.')}/>}</section></>}

/* ───────── Documents ───────── */
function Documents({manage}:{manage:boolean}){const {t,lang}=useUI();const vehicles=useVehicles();const {rows,load}=useTable('vehicle_documents','*',['expires_on',true]);const [edit,setEdit]=useState<Row|null>(null),[vehicle,setVehicle]=useState('');
 const plate=(id:string)=>vehicles.find(v=>v.id===id)?.plate_number||'—';
 // Show the latest document of each kind per vehicle first; older (renewed) ones after it.
 const list=(rows||[]).filter(d=>!vehicle||d.vehicle_id===vehicle);
 const latest=new Set(Object.values(list.reduce((m:Record<string,Row>,d)=>{const k=d.vehicle_id+d.kind;if(!m[k]||(d.expires_on||'')>(m[k].expires_on||''))m[k]=d;return m},{})).map(d=>d.id));
 const fields:Field[]=[{key:'vehicle_id',label:t('العربية','Vehicle'),type:'select',required:true,options:vehicles.map(v=>[v.id,v.plate_number])},{key:'kind',label:t('نوع المستند','Document'),type:'select',required:true,options:Object.entries(DOC_KINDS).map(([k,[a,e]])=>[k,t(a,e)])},
  {key:'number',label:t('الرقم','Number')},{key:'title',label:t('وصف (اختياري)','Description (optional)')},{key:'issued_on',label:t('تاريخ الإصدار','Issued on'),type:'date'},{key:'expires_on',label:t('تاريخ الانتهاء','Expires on'),type:'date',hint:t('التنبيه بيظهر قبلها بـ 30 يوم','An alert appears 30 days before')},
  {key:'cost',label:t('التكلفة (ج.م)','Cost (EGP)'),type:'number',step:'0.01'},{key:'_photo',label:t('صورة المستند','Photo of the document'),type:'photo'},{key:'notes',label:t('ملاحظات','Notes'),type:'textarea'}];
 return <><div className="ops-toolbar"><select value={vehicle} onChange={e=>setVehicle(e.target.value)}><option value="">{t('كل العربيات','All vehicles')}</option>{vehicles.map(v=><option key={v.id} value={v.id}>{v.plate_number}</option>)}</select>{manage&&<button className="btn btn-red" disabled={!vehicles.length} onClick={()=>setEdit({kind:'license',vehicle_id:vehicle||vehicles[0]?.id})}><Plus size={17}/>{t('إضافة مستند','Add document')}</button>}</div>
  <div className="card table-scroll"><table className="data-table stack-table"><thead><tr>{[['العربية','Vehicle'],['المستند','Document'],['الرقم','Number'],['ينتهي','Expires'],['الحالة','Status'],['التكلفة','Cost'],['','']].map(([a,e],i)=><th key={i}>{t(a,e)}</th>)}</tr></thead><tbody>
   {list.sort((a,b)=>Number(latest.has(b.id))-Number(latest.has(a.id))).map(d=><tr key={d.id} className={latest.has(d.id)?'':'faded'}><td data-label={t('العربية','Vehicle')}><b>{plate(d.vehicle_id)}</b></td><td data-label={t('المستند','Document')}>{t(DOC_KINDS[d.kind][0],DOC_KINDS[d.kind][1])}{d.title?<small className="muted"> · {d.title}</small>:null}</td><td data-label={t('الرقم','Number')}>{d.number||'—'}</td><td data-label={t('ينتهي','Expires')}>{fmtDate(d.expires_on,lang)}</td><td data-label={t('الحالة','Status')}>{latest.has(d.id)?<ExpiryBadge date={d.expires_on}/>:<span className="pill pill-gray">{t('اتجدد','Renewed')}</span>}</td><td data-label={t('التكلفة','Cost')}>{money(d.cost,t)}</td>
    <td className="actions"><div className="btn-row end">{d.file_key&&<button className="icon-btn" aria-label={t('عرض','View')} onClick={()=>openFile(d.file_key)}><Eye size={16}/></button>}{manage&&<><button className="icon-btn" aria-label={t('تعديل','Edit')} onClick={()=>setEdit(d)}><Pencil size={16}/></button><button className="icon-btn" aria-label={t('حذف','Delete')} onClick={async()=>{if(await remove('vehicle_documents',d.id,t))load()}}><Trash2 size={16}/></button></>}</div></td></tr>)}</tbody></table>
   {rows===null?<div className="center-block"><span className="spinner"/></div>:!list.length&&<Empty title={t('مفيش مستندات','No documents')} detail={t('ضيف رخصة وتأمين وفحص كل عربية عشان يجيلك تنبيه قبل ما تنتهي.','Add each vehicle’s licence, insurance and inspection to be alerted before they expire.')}/>}</div>
  {edit&&<FormModal title={edit.id?t('تعديل مستند','Edit document'):t('إضافة مستند','Add document')} fields={fields} initial={edit} onClose={()=>setEdit(null)} onSave={async(v,photo)=>{if(photo)v.file_key=(await uploadImage(photo,'factory-files','fleet/'+v.vehicle_id)).path;await save('vehicle_documents',v,['cost']);toast.success(t('اتحفظ','Saved'));load()}}/>}</>}

/* ───────── Maintenance plan ───────── */
function Maintenance({manage,go}:{manage:boolean,go:(k:string)=>void}){const {t,lang,version}=useUI();const vehicles=useVehicles();const types=useTable('vehicle_types','id,name_ar,name_en').rows||[];const plans=useTable('maintenance_plans','*',['item',true]);
 const [status,setStatus]=useState<Row[]|null>(null),[edit,setEdit]=useState<Row|null>(null),[filter,setFilter]=useState('attention'),[order,setOrder]=useState<Row|null>(null);
 const loadStatus=()=>db().rpc('fleet_maintenance_status').then(r=>{if(r.error)toast.error(message(r.error));setStatus(r.data||[])});useEffect(()=>{loadStatus()},[version,plans.rows]);
 const shown=(status||[]).filter(s=>filter==='all'||(filter==='attention'?s.status==='due'||s.status==='soon':s.status===filter)).sort((a,b)=>Number(b.ratio??-1)-Number(a.ratio??-1));
 const label:Record<string,[string,string,string]>={due:['مستحقة','Due','pill-red'],soon:['قرّبت','Soon','pill-amber'],ok:['تمام','OK','pill-green'],unknown:['مش متسجلة','Never logged','pill-gray']};
 const fields:Field[]=[{key:'item',label:t('البند','Item'),required:true},{key:'category',label:t('بيتسجل في مصروفات','Logged as expense type'),type:'select',required:true,options:Object.entries(SERVICE).map(([k,[a,e]])=>[k,t(a,e)])},
  {key:'part_keyword',label:t('كلمة في اسم القطعة (اختياري)','Word in the part name (optional)'),hint:t('مثلاً "فرامل": بيدور على آخر قطعة غيار اسمها فيه الكلمة دي','e.g. "brake": matches the last spare part whose name contains it')},
  {key:'every_km',label:t('كل كام كيلو','Every km'),type:'number'},{key:'every_days',label:t('أو كل كام يوم','Or every days'),type:'number'},
  {key:'type_id',label:t('لنوع عربيات معين','Only for a vehicle type'),type:'select',options:types.map(x=>[x.id,lang==='ar'?x.name_ar:x.name_en])},{key:'vehicle_id',label:t('أو لعربية واحدة','Or one vehicle'),type:'select',options:vehicles.map(v=>[v.id,v.plate_number])}];
 return <><div className="ops-toolbar"><div className="chip-row wrap">{[['attention','محتاجة متابعة','Needs attention'],['due','مستحقة','Due'],['soon','قرّبت','Soon'],['unknown','مش متسجلة','Never logged'],['all','الكل','All']].map(([k,a,e])=><button key={k} className={'chip'+(filter===k?' active':'')} onClick={()=>setFilter(k)}>{t(a,e)}</button>)}</div></div>
  <div className="card table-scroll"><table className="data-table stack-table"><thead><tr>{[['العربية','Vehicle'],['البند','Item'],['آخر مرة','Last done'],['من وقتها','Since'],['الميعاد الجاي','Next due'],['','']].map(([a,e],i)=><th key={i}>{t(a,e)}</th>)}</tr></thead><tbody>
   {shown.map(s=>{const [a,e,c]=label[s.status];return <tr key={s.vehicle_id+s.plan_id}><td data-label={t('العربية','Vehicle')}><b>{s.plate_number}</b></td><td data-label={t('البند','Item')}>{s.item}</td><td data-label={t('آخر مرة','Last done')}>{s.last_date?fmtDate(s.last_date,lang):'—'}{s.last_odometer!=null?<small className="muted"> · {num(s.last_odometer)} {t('كم','km')}</small>:null}</td>
    <td data-label={t('من وقتها','Since')}>{s.km_since!=null?num(Math.round(s.km_since))+' '+t('كم','km'):''}{s.km_since!=null&&s.days_since!=null?' · ':''}{s.days_since!=null?s.days_since+' '+t('يوم','d'):''}{s.km_since==null&&s.days_since==null?'—':''}
     {s.ratio!=null&&<div className="ops-progress"><span className={'r-'+s.status} style={{width:Math.min(100,Number(s.ratio)*100)+'%'}}/></div>}</td>
    <td data-label={t('الميعاد الجاي','Next due')}>{s.due_km!=null?num(Math.round(s.due_km))+' '+t('كم','km'):''}{s.due_km!=null&&s.due_date?' · ':''}{s.due_date?fmtDate(s.due_date,lang):''}{s.due_km==null&&!s.due_date?'—':''} <span className={'pill '+c}>{t(a,e)}</span></td>
    <td className="actions">{manage&&(s.status==='due'||s.status==='soon'||s.status==='unknown')&&<button className="btn btn-ghost btn-sm" onClick={()=>setOrder({vehicle_id:s.vehicle_id,title:s.item,category:s.category==='other'?'maintenance':s.category,priority:s.status==='due'?'high':'normal'})}><ClipboardList size={15}/>{t('أمر شغل','Work order')}</button>}</td></tr>})}</tbody></table>
   {status===null?<div className="center-block"><span className="spinner"/></div>:!shown.length&&<Empty title={filter==='attention'?t('كل الصيانات في ميعادها','All services are on schedule'):t('مفيش بنود','Nothing here')} detail={t('آخر صيانة بتتحسب من المصروفات المتسجلة لكل عربية (تغيير زيت، كاوتش، بطارية، قطع غيار...).','The last service comes from each vehicle’s logged expenses (oil change, tyres, battery, parts...).')}/>}</div>
  <section className="card"><div className="card-head"><h3>{t('بنود الخطة','Plan items')}</h3>{manage&&<button className="btn btn-outline btn-sm" onClick={()=>setEdit({category:'maintenance'})}><Plus size={15}/>{t('بند جديد','New item')}</button>}</div>
   <ul className="ops-plain">{(plans.rows||[]).map(p=><li key={p.id}><span><b>{p.item}</b><small className="muted">{[p.every_km&&t(`كل ${num(p.every_km)} كم`,`every ${num(p.every_km)} km`),p.every_days&&t(`كل ${p.every_days} يوم`,`every ${p.every_days} days`),p.vehicle_id?vehicles.find(v=>v.id===p.vehicle_id)?.plate_number:p.type_id?types.find(x=>x.id===p.type_id)?.[lang==='ar'?'name_ar':'name_en']:t('كل العربيات','all vehicles')].filter(Boolean).join(' · ')}</small></span>
    {manage&&<span className="btn-row"><button className="icon-btn" onClick={()=>setEdit(p)} aria-label={t('تعديل','Edit')}><Pencil size={16}/></button><button className="icon-btn" aria-label={t('حذف','Delete')} onClick={async()=>{if(await remove('maintenance_plans',p.id,t))plans.load()}}><Trash2 size={16}/></button></span>}</li>)}</ul></section>
  {edit&&<FormModal title={edit.id?t('تعديل بند','Edit item'):t('بند صيانة جديد','New maintenance item')} fields={fields} initial={edit} onClose={()=>setEdit(null)} onSave={async v=>{await save('maintenance_plans',v,['every_km','every_days']);plans.load()}}/>}
  {order&&<WorkOrderForm initial={order} vehicles={vehicles} onClose={()=>setOrder(null)} onSaved={()=>{toast.success(t('اتعمل أمر الشغل','Work order created'));go('orders')}}/>}</>}

/* ───────── Work orders ───────── */
function WorkOrderForm({initial,vehicles,onClose,onSaved}:{initial:Row,vehicles:Row[],onClose:()=>void,onSaved:()=>void}){const {t}=useUI();
 return <FormModal title={initial.id?t(`أمر شغل #${initial.number}`,`Work order #${initial.number}`):t('أمر شغل جديد','New work order')} initial={{status:'open',priority:'normal',category:'maintenance',opened_on:today(),...initial}} onClose={onClose}
  fields={[{key:'vehicle_id',label:t('العربية','Vehicle'),type:'select',required:true,options:vehicles.map(v=>[v.id,v.plate_number])},{key:'title',label:t('المطلوب','What is needed'),required:true},{key:'category',label:t('النوع','Type'),type:'select',required:true,options:Object.entries(SERVICE).filter(([k])=>k!=='other').map(([k,[a,e]])=>[k,t(a,e)])},
   {key:'priority',label:t('الأولوية','Priority'),type:'select',required:true,options:Object.entries(PRIORITY).map(([k,[a,e]])=>[k,t(a,e)])},{key:'status',label:t('الحالة','Status'),type:'select',required:true,options:Object.entries(WO_STATUS).filter(([k])=>k!=='done').map(([k,[a,e]])=>[k,t(a,e)])},
   {key:'due_on',label:t('مطلوب يخلص يوم','Due on'),type:'date'},{key:'workshop',label:t('الورشة','Workshop')},{key:'odometer',label:t('العداد','Odometer'),type:'number'},{key:'labor_cost',label:t('المصنعية (ج.م)','Labour (EGP)'),type:'number',step:'0.01'},{key:'description',label:t('تفاصيل','Details'),type:'textarea'}]}
  onSave={async v=>{await save('work_orders',v,['odometer','labor_cost']);onSaved()}}/>}
function Orders({manage}:{manage:boolean}){const {t,lang}=useUI();const vehicles=useVehicles();const orders=useTable('work_orders','*',['opened_on',false]);const parts=useTable('parts','id,name,unit,qty,unit_cost',['name',true]);const moves=useTable('part_movements','id,part_id,qty,unit_cost,work_order_id,kind');
 const [edit,setEdit]=useState<Row|null>(null),[use,setUse]=useState<Row|null>(null),[filter,setFilter]=useState('active');
 const plate=(id:string)=>vehicles.find(v=>v.id===id)?.plate_number||'—';
 const partsCost=(id:string)=>(moves.rows||[]).filter(m=>m.work_order_id===id&&m.kind==='out').reduce((s,m)=>s+Number(m.qty)*Number(m.unit_cost||0),0);
 const list=(orders.rows||[]).filter(o=>filter==='all'||(filter==='active'?o.status==='open'||o.status==='in_progress':o.status===filter));
 const reload=()=>{orders.load();parts.load();moves.load()};
 return <><div className="ops-toolbar"><div className="chip-row wrap">{[['active','المفتوحة','Active'],['done','المقفولة','Done'],['all','الكل','All']].map(([k,a,e])=><button key={k} className={'chip'+(filter===k?' active':'')} onClick={()=>setFilter(k)}>{t(a,e)}</button>)}</div>{manage&&<button className="btn btn-red" disabled={!vehicles.length} onClick={()=>setEdit({vehicle_id:vehicles[0]?.id})}><Plus size={17}/>{t('أمر شغل جديد','New work order')}</button>}</div>
  <div className="card table-scroll"><table className="data-table stack-table"><thead><tr>{[['#','#'],['العربية','Vehicle'],['المطلوب','Job'],['الحالة','Status'],['مطلوب يوم','Due'],['المصنعية','Labour'],['قطع الغيار','Parts'],['الإجمالي','Total'],['','']].map(([a,e],i)=><th key={i}>{t(a,e)}</th>)}</tr></thead><tbody>
   {list.map(o=>{const pc=partsCost(o.id);const late=(o.status==='open'||o.status==='in_progress')&&o.due_on&&o.due_on<today();return <tr key={o.id}><td data-label="#">{o.number}</td><td data-label={t('العربية','Vehicle')}><b>{plate(o.vehicle_id)}</b></td><td data-label={t('المطلوب','Job')} className="wrap">{o.title}{o.priority==='high'&&<span className="pill pill-red"> {t('عاجل','Urgent')}</span>}{o.workshop?<small className="muted"> · {o.workshop}</small>:null}</td>
    <td data-label={t('الحالة','Status')}><span className={'pill '+WO_STATUS[o.status][2]}>{t(WO_STATUS[o.status][0],WO_STATUS[o.status][1])}</span></td><td data-label={t('مطلوب يوم','Due')}>{o.due_on?<span className={late?'text-red':''}>{fmtDate(o.due_on,lang)}</span>:'—'}</td>
    <td data-label={t('المصنعية','Labour')}>{money(o.labor_cost,t)}</td><td data-label={t('قطع الغيار','Parts')}>{pc?money(pc,t):'—'}</td><td data-label={t('الإجمالي','Total')}><b>{money(Number(o.labor_cost)+pc,t)}</b></td>
    <td className="actions">{manage&&o.status!=='done'&&o.status!=='cancelled'&&<div className="btn-row end"><button className="btn btn-ghost btn-sm" onClick={()=>setUse(o)}><Package size={15}/>{t('صرف قطعة','Use a part')}</button><button className="btn btn-ghost btn-sm" onClick={async()=>{const odo=prompt(t('قراءة العداد دلوقتي (اختياري)','Odometer now (optional)'),o.odometer??'');if(odo===null)return;try{unwrap(await db().rpc('close_work_order',{target:o.id,odometer_now:odo?Number(odo):null}));toast.success(t('اتقفل أمر الشغل واتسجلت تكلفته في مصروفات العربية','Closed; its cost was added to the vehicle’s expenses'));reload()}catch(e){toast.error(message(e))}}}><CheckCheck size={15}/>{t('قفل','Close')}</button><button className="icon-btn" aria-label={t('تعديل','Edit')} onClick={()=>setEdit(o)}><Pencil size={16}/></button></div>}</td></tr>})}</tbody></table>
   {orders.rows===null?<div className="center-block"><span className="spinner"/></div>:!list.length&&<Empty title={t('مفيش أوامر شغل','No work orders')} detail={t('افتح أمر شغل لأي عربية رايحة الورشة، وصرف عليه قطع الغيار، ولما يتقفل تكلفته بتتسجل في مصروفات العربية لوحدها.','Open a work order for any vehicle going to the workshop and issue parts to it; when it is closed its cost is added to the vehicle’s expenses.')}/>}</div>
  {edit&&<WorkOrderForm initial={edit} vehicles={vehicles} onClose={()=>setEdit(null)} onSaved={reload}/>}
  {use&&<FormModal title={t(`صرف قطعة لأمر شغل #${use.number}`,`Issue a part to work order #${use.number}`)} initial={{part_id:parts.rows?.[0]?.id,qty:1}} onClose={()=>setUse(null)}
   fields={[{key:'part_id',label:t('القطعة','Part'),type:'select',required:true,options:(parts.rows||[]).map(p=>[p.id,`${p.name} (${t('موجود','in stock')}: ${num(p.qty)} ${p.unit})`])},{key:'qty',label:t('الكمية','Quantity'),type:'number',required:true,step:'0.01'}]}
   onSave={async v=>{const p=(parts.rows||[]).find(x=>x.id===v.part_id);unwrap(await db().from('part_movements').insert({part_id:v.part_id,kind:'out',qty:Number(v.qty),unit_cost:p?.unit_cost??null,work_order_id:use.id,vehicle_id:use.vehicle_id}));toast.success(t('اتصرفت القطعة','Part issued'));reload()}}/>}</>}

/* ───────── Parts store ───────── */
function Parts({manage}:{manage:boolean}){const {t,lang}=useUI();const vehicles=useVehicles();const parts=useTable('parts','*',['name',true]);const [edit,setEdit]=useState<Row|null>(null),[move,setMove]=useState<{part:Row,kind:string}|null>(null),[history,setHistory]=useState<Row|null>(null),[q,setQ]=useState('');
 const list=(parts.rows||[]).filter(p=>!q||p.name.includes(q)||(p.sku||'').toLowerCase().includes(q.toLowerCase()));
 const value=list.reduce((s,p)=>s+Math.max(0,Number(p.qty))*Number(p.unit_cost||0),0);
 return <><div className="ops-toolbar"><input type="search" placeholder={t('دوّر باسم القطعة أو الكود','Search by name or code')} value={q} onChange={e=>setQ(e.target.value)}/><span className="muted">{t('قيمة المخزن: ','Stock value: ')}<b>{money(value,t)}</b></span>{manage&&<button className="btn btn-red" onClick={()=>setEdit({unit:'قطعة',min_qty:0})}><Plus size={17}/>{t('قطعة جديدة','New part')}</button>}</div>
  <div className="card table-scroll"><table className="data-table stack-table"><thead><tr>{[['القطعة','Part'],['الكود','Code'],['الموجود','In stock'],['الحد الأدنى','Minimum'],['سعر الوحدة','Unit cost'],['المكان','Location'],['','']].map(([a,e],i)=><th key={i}>{t(a,e)}</th>)}</tr></thead><tbody>
   {list.map(p=>{const low=Number(p.min_qty)>0&&Number(p.qty)<=Number(p.min_qty);return <tr key={p.id}><td data-label={t('القطعة','Part')}><b>{p.name}</b></td><td data-label={t('الكود','Code')}>{p.sku||'—'}</td><td data-label={t('الموجود','In stock')}><span className={'pill '+(Number(p.qty)<=0?'pill-red':low?'pill-amber':'pill-green')}>{num(p.qty)} {p.unit}</span></td><td data-label={t('الحد الأدنى','Minimum')}>{num(p.min_qty)}</td><td data-label={t('سعر الوحدة','Unit cost')}>{money(p.unit_cost,t)}</td><td data-label={t('المكان','Location')}>{p.location||'—'}</td>
    <td className="actions"><div className="btn-row end">{manage&&<><button className="btn btn-ghost btn-sm" onClick={()=>setMove({part:p,kind:'in'})}><ArrowDownToLine size={15}/>{t('وارد','Receive')}</button><button className="btn btn-ghost btn-sm" onClick={()=>setMove({part:p,kind:'out'})}><ArrowUpFromLine size={15}/>{t('صرف','Issue')}</button></>}<button className="icon-btn" aria-label={t('الحركة','History')} onClick={()=>setHistory(p)}><Eye size={16}/></button>{manage&&<button className="icon-btn" aria-label={t('تعديل','Edit')} onClick={()=>setEdit(p)}><Pencil size={16}/></button>}</div></td></tr>})}</tbody></table>
   {parts.rows===null?<div className="center-block"><span className="spinner"/></div>:!list.length&&<Empty title={t('المخزن فاضي','The store is empty')} detail={t('ضيف قطع الغيار اللي عندكم (فلاتر، زيوت، تيل فرامل...) وحط لكل واحدة حد أدنى عشان يجيلك تنبيه لما تقرّب تخلص.','Add the parts you keep (filters, oil, brake pads...) with a minimum, and you will be alerted when one runs low.')}/>}</div>
  {edit&&<FormModal title={edit.id?t('تعديل قطعة','Edit part'):t('قطعة جديدة','New part')} initial={edit} onClose={()=>setEdit(null)} onSave={async v=>{const {qty:_,...rest}=v;await save('parts',edit.id?rest:v,['min_qty','unit_cost']);parts.load()}}
   fields={[{key:'name',label:t('اسم القطعة','Part name'),required:true},{key:'sku',label:t('الكود (اختياري)','Code (optional)')},{key:'unit',label:t('الوحدة','Unit'),required:true},{key:'min_qty',label:t('الحد الأدنى','Minimum stock'),type:'number',step:'0.01'},{key:'unit_cost',label:t('سعر الوحدة (ج.م)','Unit cost (EGP)'),type:'number',step:'0.01'},{key:'location',label:t('مكانها في المخزن','Shelf / location')},{key:'notes',label:t('ملاحظات','Notes'),type:'textarea'}]}/>}
  {move&&<FormModal title={(move.kind==='in'?t('وارد: ','Receive: '):t('صرف: ','Issue: '))+move.part.name} initial={{qty:'',unit_cost:move.part.unit_cost??'',moved_on:today()}} onClose={()=>setMove(null)}
   fields={move.kind==='in'?[{key:'qty',label:t('الكمية','Quantity'),type:'number',required:true,step:'0.01'},{key:'unit_cost',label:t('سعر الوحدة (ج.م)','Unit cost (EGP)'),type:'number',step:'0.01'},{key:'supplier',label:t('المورد','Supplier')},{key:'moved_on',label:t('التاريخ','Date'),type:'date',required:true}]
    :[{key:'qty',label:t('الكمية','Quantity'),type:'number',required:true,step:'0.01'},{key:'vehicle_id',label:t('للعربية','For vehicle'),type:'select',options:vehicles.map(v=>[v.id,v.plate_number])},{key:'moved_on',label:t('التاريخ','Date'),type:'date',required:true},{key:'notes',label:t('ملاحظات','Notes'),type:'textarea'}]}
   onSave={async v=>{unwrap(await db().from('part_movements').insert({...clean(v,['qty','unit_cost']),part_id:move.part.id,kind:move.kind,unit_cost:v.unit_cost!==''&&v.unit_cost!=null?Number(v.unit_cost):move.part.unit_cost??null}));toast.success(t('اتسجلت الحركة','Saved'));parts.load()}}/>}
  {history&&<PartHistory part={history} vehicles={vehicles} onClose={()=>setHistory(null)} lang={lang}/>}</>}
function PartHistory({part,vehicles,onClose,lang}:{part:Row,vehicles:Row[],onClose:()=>void,lang:string}){const {t}=useUI();const [rows,setRows]=useState<Row[]|null>(null);useEffect(()=>{db().from('part_movements').select('*').eq('part_id',part.id).order('moved_on',{ascending:false}).limit(200).then(r=>setRows(r.data||[]))},[]);
 return <Modal title={t('حركة ','Movements: ')+part.name} onClose={onClose}>{rows===null?<div className="center-block"><span className="spinner"/></div>:rows.length?<ul className="ops-plain">{rows.map(m=><li key={m.id}><span><b>{m.kind==='in'?t('وارد','In'):m.kind==='out'?t('صرف','Out'):t('تسوية','Adjust')} {num(m.qty)} {part.unit}</b><small className="muted">{fmtDate(m.moved_on,lang)}{m.vehicle_id?' · '+(vehicles.find(v=>v.id===m.vehicle_id)?.plate_number||''):''}{m.supplier?' · '+m.supplier:''}</small></span><span>{m.unit_cost!=null?money(Number(m.unit_cost)*Number(m.qty),t):''}</span></li>)}</ul>:<p className="muted">{t('مفيش حركة','No movements')}</p>}</Modal>}

/* ───────── Drivers ───────── */
function Drivers({manage}:{manage:boolean}){const {t,lang}=useUI();const vehicles=useVehicles();const reps=useDrivers();const profiles=useTable('driver_profiles');const assignments=useTable('vehicle_assignments','*',['started_on',false]);const violations=useTable('driver_violations','*',['happened_on',false]);
 const [edit,setEdit]=useState<Row|null>(null),[handover,setHandover]=useState<Row|null>(null),[violation,setViolation]=useState<Row|null>(null);
 const profileOf=(id:string)=>(profiles.rows||[]).find(p=>p.profile_id===id);
 const current=(id:string)=>(assignments.rows||[]).find(a=>a.driver_id===id&&!a.ended_on);
 const plate=(id:string)=>vehicles.find(v=>v.id===id)?.plate_number||'—';
 const name=(a:Row)=>a.driver_id?reps.find(r=>r.id===a.driver_id)?.display_name||a.driver_name||'—':a.driver_name;
 const repOptions=reps.map(r=>[r.id,r.display_name] as [string,string]);
 return <><div className="ops-toolbar">{manage&&<><button className="btn btn-red" disabled={!vehicles.length} onClick={()=>setHandover({vehicle_id:vehicles[0]?.id,driver_id:reps[0]?.id||'',started_on:today()})}><ArrowLeftRight size={17}/>{t('تسليم عربية','Hand over a vehicle')}</button><button className="btn btn-outline" onClick={()=>setViolation({kind:'traffic_fine',happened_on:today(),profile_id:reps[0]?.id||''})}><TriangleAlert size={17}/>{t('تسجيل مخالفة','Log a violation')}</button></>}</div>
  <div className="card table-scroll"><table className="data-table stack-table"><thead><tr>{[['السواق','Driver'],['الموبايل','Phone'],['رخصة السواقة','Licence'],['العربية اللي معاه','Vehicle now'],['المخالفات','Violations'],['','']].map(([a,e],i)=><th key={i}>{t(a,e)}</th>)}</tr></thead><tbody>
   {reps.map(r=>{const p=profileOf(r.id)||{};const a=current(r.id);const v=(violations.rows||[]).filter(x=>x.profile_id===r.id);return <tr key={r.id}><td data-label={t('السواق','Driver')}><b>{r.display_name}</b></td><td data-label={t('الموبايل','Phone')} dir="ltr">{p.phone||'—'}</td><td data-label={t('رخصة السواقة','Licence')}>{p.license_number?<>{p.license_number} </>:null}<ExpiryBadge date={p.license_expires_on}/></td>
    <td data-label={t('العربية اللي معاه','Vehicle now')}>{a?<>{plate(a.vehicle_id)} <small className="muted">{t('من ','since ')}{fmtDate(a.started_on,lang)}</small></>:'—'}</td><td data-label={t('المخالفات','Violations')}>{v.length?<span className="pill pill-red">{v.length} · {money(v.reduce((s,x)=>s+Number(x.amount||0),0),t)}</span>:'0'}</td>
    <td className="actions">{manage&&<button className="icon-btn" aria-label={t('تعديل','Edit')} onClick={()=>setEdit({...p,profile_id:r.id,_name:r.display_name})}><Pencil size={16}/></button>}</td></tr>})}</tbody></table>
   {!reps.length&&<Empty title={t('مفيش مناديب','No reps yet')} detail={t('السواقين هما حسابات المناديب. ضيفهم من صفحة الموظفين.','Drivers are the rep accounts; add them on the Staff page.')}/>}</div>
  <div className="ops-two"><section className="card"><div className="card-head"><h3>{t('سجل تسليم العربيات','Vehicle handovers')}</h3></div><ul className="ops-plain">{(assignments.rows||[]).slice(0,30).map(a=><li key={a.id}><span><b>{plate(a.vehicle_id)} ← {name(a)}</b><small className="muted">{fmtDate(a.started_on,lang)} – {a.ended_on?fmtDate(a.ended_on,lang):t('لحد دلوقتي','now')}{a.odometer_start!=null?` · ${num(a.odometer_start)}${a.odometer_end!=null?' → '+num(a.odometer_end):''} ${t('كم','km')}`:''}</small></span>{!a.ended_on&&<span className="pill pill-green">{t('معاه دلوقتي','Current')}</span>}</li>)}</ul>{!assignments.rows?.length&&<p className="muted">{t('لسه مفيش تسليمات','No handovers yet')}</p>}</section>
   <section className="card"><div className="card-head"><h3>{t('المخالفات','Violations')}</h3></div><ul className="ops-plain">{(violations.rows||[]).slice(0,30).map(v=><li key={v.id}><span><b>{t(VIOLATIONS[v.kind][0],VIOLATIONS[v.kind][1])} — {v.profile_id?reps.find(r=>r.id===v.profile_id)?.display_name:v.driver_name}</b><small className="muted">{fmtDate(v.happened_on,lang)}{v.vehicle_id?' · '+plate(v.vehicle_id):''}{v.notes?' · '+v.notes:''}</small></span><span className="btn-row">{v.amount?<b>{money(v.amount,t)}</b>:null}{v.file_key&&<button className="icon-btn" onClick={()=>openFile(v.file_key)} aria-label={t('عرض','View')}><Eye size={16}/></button>}{manage&&<button className="icon-btn" aria-label={t('حذف','Delete')} onClick={async()=>{if(await remove('driver_violations',v.id,t))violations.load()}}><Trash2 size={16}/></button>}</span></li>)}</ul>{!violations.rows?.length&&<p className="muted">{t('مفيش مخالفات','No violations')}</p>}</section></div>
  {edit&&<FormModal title={edit._name} initial={edit} onClose={()=>setEdit(null)} onSave={async v=>{const body=clean(v);body.updated_at=new Date().toISOString();unwrap(await db().from('driver_profiles').upsert(body));profiles.load()}}
   fields={[{key:'phone',label:t('الموبايل','Phone')},{key:'license_number',label:t('رقم رخصة السواقة','Licence number')},{key:'license_class',label:t('درجة الرخصة','Licence class')},{key:'license_expires_on',label:t('تنتهي يوم','Expires on'),type:'date',hint:t('التنبيه بيظهر قبلها بـ 30 يوم','An alert appears 30 days before')},{key:'national_id',label:t('الرقم القومي','National ID')},{key:'hired_on',label:t('تاريخ التعيين','Hired on'),type:'date'},{key:'notes',label:t('ملاحظات','Notes'),type:'textarea'}]}/>}
  {handover&&<FormModal title={t('تسليم عربية','Hand over a vehicle')} initial={handover} onClose={()=>setHandover(null)} onSave={async v=>{
    // The vehicle's previous holder gives it back the same day.
    const open=(assignments.rows||[]).find(a=>a.vehicle_id===v.vehicle_id&&!a.ended_on);
    if(open)unwrap(await db().from('vehicle_assignments').update({ended_on:v.started_on<open.started_on?open.started_on:v.started_on,odometer_end:v.odometer_start?Number(v.odometer_start):null}).eq('id',open.id));
    unwrap(await db().from('vehicle_assignments').insert(clean({...v,driver_name:v.driver_id?reps.find(r=>r.id===v.driver_id)?.display_name:v.driver_name},['odometer_start'])));toast.success(t('اتسجل التسليم','Handover saved'));assignments.load()}}
   fields={[{key:'vehicle_id',label:t('العربية','Vehicle'),type:'select',required:true,options:vehicles.map(v=>[v.id,v.plate_number])},{key:'driver_id',label:t('اتسلمت لـ','Handed to'),type:'select',options:repOptions},{key:'driver_name',label:t('أو اسم سواق (من غير حساب)','Or a driver without an account')},{key:'started_on',label:t('التاريخ','Date'),type:'date',required:true},{key:'odometer_start',label:t('العداد وقت التسليم','Odometer at handover'),type:'number'},{key:'notes',label:t('ملاحظات (حالة العربية...)','Notes (vehicle condition...)'),type:'textarea'}]}/>}
  {violation&&<FormModal title={t('تسجيل مخالفة','Log a violation')} initial={violation} onClose={()=>setViolation(null)} onSave={async(v,photo)=>{if(photo){if(!v.vehicle_id)throw Error(t('اختار العربية عشان ترفع صورة','Choose the vehicle to attach a photo'));v.file_key=(await uploadImage(photo,'factory-files','fleet/'+v.vehicle_id)).path}await save('driver_violations',v,['amount']);violations.load()}}
   fields={[{key:'profile_id',label:t('السواق','Driver'),type:'select',options:repOptions},{key:'driver_name',label:t('أو اسم سواق','Or a driver name')},{key:'kind',label:t('النوع','Type'),type:'select',required:true,options:Object.entries(VIOLATIONS).map(([k,[a,e]])=>[k,t(a,e)])},{key:'happened_on',label:t('التاريخ','Date'),type:'date',required:true},{key:'vehicle_id',label:t('العربية','Vehicle'),type:'select',options:vehicles.map(v=>[v.id,v.plate_number])},{key:'amount',label:t('المبلغ (ج.م)','Amount (EGP)'),type:'number',step:'0.01'},{key:'_photo',label:t('صورة المخالفة','Photo'),type:'photo'},{key:'notes',label:t('ملاحظات','Notes'),type:'textarea'}]}/>}</>}

/* ───────── Places & visits ───────── */
function Places({manage}:{manage:boolean}){const {t,lang}=useUI();const places=usePlaces();const reps=useDrivers();const [edit,setEdit]=useState<Row|null>(null),[picking,setPicking]=useState(false),[from,setFrom]=useState(today()),[to,setTo]=useState(today()),[rep,setRep]=useState(''),[visits,setVisits]=useState<Row[]|null>(null);
 useEffect(()=>{setVisits(null);db().rpc('tracking_visits',{from_date:from,to_date:to,rep:rep||null}).then(r=>{if(r.error){toast.error(message(r.error));setVisits([])}else setVisits(r.data||[])})},[from,to,rep,places.rows]);
 const perPlace=useMemo(()=>{const m=new Map<string,{n:number,min:number,reps:Set<string>}>();for(const v of visits||[]){const x=m.get(v.place_id)||{n:0,min:0,reps:new Set()};x.n++;x.min+=Number(v.minutes);x.reps.add(v.rep_name);m.set(v.place_id,x)}return m},[visits]);
 const fields:Field[]=[{key:'name',label:t('الاسم','Name'),required:true},{key:'kind',label:t('النوع','Type'),type:'select',required:true,options:Object.entries(PLACE_KINDS).map(([k,[a,e]])=>[k,t(a,e)])},{key:'radius_m',label:t('نطاق المكان (متر)','Radius (m)'),type:'number',required:true,hint:t('المندوب بيتحسب "زار" المكان لو فضل جوه النطاق ده 3 دقايق أو أكتر','A rep has visited when they stay inside it for 3+ minutes')},{key:'lat',label:t('خط العرض','Latitude'),type:'number',required:true,step:'any'},{key:'lng',label:t('خط الطول','Longitude'),type:'number',required:true,step:'any'},{key:'phone',label:t('التليفون','Phone')},{key:'address',label:t('العنوان','Address'),full:true},{key:'notes',label:t('ملاحظات','Notes'),type:'textarea'}];
 return <><div className="ops-toolbar">{manage&&<button className={'btn '+(picking?'btn-dark':'btn-red')} onClick={()=>setPicking(p=>!p)}><Plus size={17}/>{picking?t('دوس على مكانه في الخريطة…','Click its spot on the map…'):t('إضافة مكان','Add a place')}</button>}<span className="muted small">{t('المصنع والمخازن والعملاء. لما المندوب يقف جوه نطاق مكان 3 دقايق أو أكتر بتتسجل زيارة.','Factory, warehouses and customers. A stay of 3+ minutes inside a place counts as a visit.')}</span></div>
  <section className="card tracking-map-card"><MapView height={420} className={picking?'picking':''} fitKey={(places.rows||[]).length?'p':'none'} deps={[places.rows,picking]} draw={(g,m)=>{drawPlaces(g,places.rows||[]);m.off('click');if(picking)m.on('click',(e:any)=>{setPicking(false);setEdit({kind:'customer',radius_m:150,lat:Number(e.latlng.lat.toFixed(6)),lng:Number(e.latlng.lng.toFixed(6))})});const pts=(places.rows||[]).map(p=>[p.lat,p.lng] as [number,number]);return pts.length?L.latLngBounds(pts).pad(.2):null}}/></section>
  <div className="ops-two"><section className="card"><div className="card-head"><h3>{t('الأماكن','Places')}</h3></div><ul className="ops-plain">{(places.rows||[]).map(p=>{const s=perPlace.get(p.id);return <li key={p.id}><span><b><i className="kind-dot" style={{background:PLACE_KINDS[p.kind][2]}}/>{p.name}</b><small className="muted">{t(PLACE_KINDS[p.kind][0],PLACE_KINDS[p.kind][1])} · {p.radius_m} {t('م','m')}{s?` · ${t(`${s.n} زيارة في الفترة`,`${s.n} visits in period`)}`:''}</small></span>{manage&&<span className="btn-row"><button className="icon-btn" aria-label={t('تعديل','Edit')} onClick={()=>setEdit(p)}><Pencil size={16}/></button><button className="icon-btn" aria-label={t('حذف','Delete')} onClick={async()=>{if(await remove('places',p.id,t))places.load()}}><Trash2 size={16}/></button></span>}</li>})}</ul>{!places.rows?.length&&<p className="muted">{t('لسه مفيش أماكن. اضغط "إضافة مكان" ودوس على مكانه في الخريطة.','No places yet. Press “Add a place” and click its spot on the map.')}</p>}</section>
   <section className="card"><div className="card-head"><h3>{t('الزيارات','Visits')}</h3><div className="ops-filters"><input type="date" value={from} max={to} onChange={e=>setFrom(e.target.value)}/><input type="date" value={to} min={from} onChange={e=>setTo(e.target.value)}/><select value={rep} onChange={e=>setRep(e.target.value)}><option value="">{t('كل المناديب','All reps')}</option>{reps.map(r=><option key={r.id} value={r.id}>{r.display_name}</option>)}</select></div></div>
    {visits===null?<div className="center-block"><span className="spinner"/></div>:visits.length?<ul className="ops-plain">{visits.map((v,i)=><li key={i}><span><b>{v.rep_name} ← {v.place_name}</b><small className="muted">{fmtDate(v.arrived_at,lang)} · {new Date(v.arrived_at).toLocaleTimeString(lang==='ar'?'ar-EG':'en-GB',{hour:'numeric',minute:'2-digit'})} – {new Date(v.left_at).toLocaleTimeString(lang==='ar'?'ar-EG':'en-GB',{hour:'numeric',minute:'2-digit'})}</small></span><span className="pill pill-gray">{v.minutes} {t('د','min')}</span></li>)}</ul>:<p className="muted">{t('مفيش زيارات في الفترة دي.','No visits in this period.')}</p>}</section></div>
  {edit&&<FormModal title={edit.id?t('تعديل مكان','Edit place'):t('مكان جديد','New place')} fields={fields} initial={edit} onClose={()=>setEdit(null)} onSave={async v=>{await save('places',v,['lat','lng','radius_m']);places.load()}}/>}</>}

/* ───────── Costs ───────── */
function Costs(){const {t,lang}=useUI();const vehicles=useVehicles();const [month,setMonth]=useState(today().slice(0,7));const [data,setData]=useState<{fuel:Row[],expenses:Row[]}|null>(null);
 useEffect(()=>{setData(null);const start=month+'-01',end=new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),1)).toISOString().slice(0,10);
  Promise.all([db().from('fuel_logs').select('vehicle_id,total_cost,distance_km,liters').gte('log_date',start).lt('log_date',end).limit(10000),db().from('vehicle_expenses').select('vehicle_id,category,amount').gte('expense_date',start).lt('expense_date',end).limit(10000)]).then(([f,e])=>setData({fuel:f.data||[],expenses:e.data||[]}))},[month]);
 const SERVICE_SET=new Set(['oil_change','maintenance','spare_part','tires','battery']);
 const rows=useMemo(()=>vehicles.map(v=>{const f=(data?.fuel||[]).filter(x=>x.vehicle_id===v.id),e=(data?.expenses||[]).filter(x=>x.vehicle_id===v.id);
  const fuel=f.reduce((s,x)=>s+Number(x.total_cost||0),0),km=f.reduce((s,x)=>s+Number(x.distance_km||0),0),liters=f.reduce((s,x)=>s+Number(x.liters||0),0);
  const service=e.filter(x=>SERVICE_SET.has(x.category)).reduce((s,x)=>s+Number(x.amount),0),other=e.filter(x=>!SERVICE_SET.has(x.category)).reduce((s,x)=>s+Number(x.amount),0);
  const total=fuel+service+other;return {v,fuel,service,other,total,km,liters,perKm:km>0?total/km:null}}).sort((a,b)=>b.total-a.total),[data,vehicles]);
 const sum=(k:'fuel'|'service'|'other'|'total'|'km')=>rows.reduce((s,r)=>s+r[k],0);const max=Math.max(1,...rows.map(r=>r.total));
 const months=[...Array(12)].map((_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);return d.toISOString().slice(0,7)});
 return <><div className="ops-toolbar"><select value={month} onChange={e=>setMonth(e.target.value)}>{months.map(m=><option key={m} value={m}>{new Date(m+'-01').toLocaleDateString(lang==='ar'?'ar-EG':'en-GB',{month:'long',year:'numeric'})}</option>)}</select>
  <button className="btn btn-outline" disabled={!rows.length} onClick={()=>exportSheet(t('تكاليف العربيات','vehicle-costs')+' '+month,[t('العربية','Vehicle'),t('السولار','Fuel'),t('الصيانة وقطع الغيار','Service & parts'),t('مصروفات تانية','Other'),t('الإجمالي','Total'),t('الكيلومترات','km'),t('تكلفة الكيلو','Cost per km')],rows.map(r=>[r.v.plate_number,Math.round(r.fuel),Math.round(r.service),Math.round(r.other),Math.round(r.total),Math.round(r.km),r.perKm!=null?Math.round(r.perKm*100)/100:'']),lang==='ar')}><FileSpreadsheet size={16}/>{t('تصدير Excel','Export to Excel')}</button></div>
  <div className="stat-cards"><div className="stat-card tone-blue"><b>{money(sum('total'),t)}</b><span>{t('إجمالي تكلفة الأسطول في الشهر','Fleet cost this month')}</span></div><div className="stat-card tone-amber"><b>{money(sum('fuel'),t)}</b><span>{t('السولار','Fuel')}</span></div><div className="stat-card tone-red"><b>{money(sum('service'),t)}</b><span>{t('الصيانة وقطع الغيار','Service & parts')}</span></div><div className="stat-card tone-gray"><b>{sum('km')>0?(sum('total')/sum('km')).toFixed(2)+' '+t('ج.م','EGP'):'—'}</b><span>{t('متوسط تكلفة الكيلو','Average cost per km')}</span></div></div>
  <div className="card table-scroll"><table className="data-table stack-table"><thead><tr>{[['العربية','Vehicle'],['السولار','Fuel'],['الصيانة وقطع الغيار','Service & parts'],['مصروفات تانية','Other'],['الإجمالي','Total'],['الكيلومترات','km'],['تكلفة الكيلو','Cost/km']].map(([a,e],i)=><th key={i}>{t(a,e)}</th>)}</tr></thead><tbody>
   {rows.map(r=><tr key={r.v.id}><td data-label={t('العربية','Vehicle')}><b>{r.v.plate_number}</b><div className="ops-progress"><span className="r-ok" style={{width:r.total/max*100+'%'}}/></div></td><td data-label={t('السولار','Fuel')}>{money(r.fuel,t)}{r.liters?<small className="muted"> · {num(Math.round(r.liters))} {t('لتر','L')}</small>:null}</td><td data-label={t('الصيانة وقطع الغيار','Service & parts')}>{money(r.service,t)}</td><td data-label={t('مصروفات تانية','Other')}>{money(r.other,t)}</td><td data-label={t('الإجمالي','Total')}><b>{money(r.total,t)}</b></td><td data-label={t('الكيلومترات','km')}>{r.km?num(Math.round(r.km)):'—'}</td><td data-label={t('تكلفة الكيلو','Cost/km')}>{r.perKm!=null?r.perKm.toFixed(2)+' '+t('ج.م','EGP'):'—'}</td></tr>)}</tbody></table>
   {data===null&&<div className="center-block"><span className="spinner"/></div>}{data&&!rows.length&&<Empty title={t('مفيش عربيات','No vehicles')}/>}</div>
  <p className="muted small">{t('الكيلومترات محسوبة من قراءات العداد في التفويلات. المصروفات التانية = رخص وتأمين ومخالفات وغسيل وكارتة.','Kilometres come from odometer readings at fuel fills. Other = licences, insurance, fines, washing and tolls.')}</p></>}
